!function(e){function i(i){for(var r,n,p=i[0],m=i[1],c=i[2],s=0,_=[];s<p.length;s++)n=p[s],Object.prototype.hasOwnProperty.call(a,n)&&a[n]&&_.push(a[n][0]),a[n]=0;for(r in m)Object.prototype.hasOwnProperty.call(m,r)&&(e[r]=m[r]);for(d&&d(i);_.length;)_.shift()();return o.push.apply(o,c||[]),t()}function t(){for(var e,i=0;i<o.length;i++){for(var t,n=o[i],p=!0,m=1;m<n.length;m++)t=n[m],0!==a[t]&&(p=!1);p&&(o.splice(i--,1),e=r(r.s=n[0]))}return e}function r(i){if(n[i])return n[i].exports;var t=n[i]={i:i,l:!1,exports:{}};return e[i].call(t.exports,t,t.exports,r),t.l=!0,t.exports}var n={},a={90:0},o=[];r.m=e,r.c=n,r.d=function(e,i,t){r.o(e,i)||Object.defineProperty(e,i,{enumerable:!0,get:t})},r.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},r.t=function(e,i){if(1&i&&(e=r(e)),8&i)return e;if(4&i&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(r.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&i&&"string"!=typeof e)for(var n in e)r.d(t,n,function(i){return e[i]}.bind(null,n));return t},r.n=function(e){var i=e&&e.__esModule?function(){return e.default}:function(){return e};return r.d(i,"a",i),i},r.o=function(e,i){return Object.prototype.hasOwnProperty.call(e,i)},r.p="";var p=window.webpackJsonp=window.webpackJsonp||[],m=p.push.bind(p);p.push=i,p=p.slice();for(var c=0;c<p.length;c++)i(p[c]);var d=m;o.push([30,0]),t()}({30:function(e,i,t){"use strict";t.r(i);var r=t(0);Object(r.a)("de","army",t(31),t(1))},31:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克","link":"de_army#de_army_tank"}],"model":"Ⅵ号虎王（虎Ⅱ）坦克","description":"<h6>综述：</h6><p>德军Ⅵ号虎王（虎Ⅱ）坦克是一种重型坦克，从1943年12月开始定型量产，到1945年3月，一共生产了480多辆，由于其炮塔由“保时捷”（有译“波尔舍”）和“亨舍尔”两个公司分别研制，故分别有“保时捷虎王”VK4502（P）和“亨舍尔虎王”VK4503（H）二种不同称呼。虎王坦克是二次大战中正式量产的重量最大，防护力最强，火力最猛的坦克，但由于车体过重造成超载，耗油量也十分大，使其机动性能大为降低，是一种防御能力强于进攻能力的坦克。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{image}}imgs/de/army/de_army_tankvi_ii_11.jpg{{image}}imgs/de/army/de_army_tankvi_ii_12.jpg{{text}}<p>注意两种炮塔的不同点：1.下图的火炮连接炮塔处装有护环的防护盾。2.下图炮塔外壁装有可挂放备用履带链防护的挂钩。</p>{{image}}imgs/de/army/de_army_tankvi_ii_13.jpg","description":"<h6>Ⅵ号虎王（虎Ⅱ）坦克（Sd.Kfz.182 Pz.Kpfw Ⅵ Aust.B TigerⅡ）</h6><p>虎王Ⅵ号（虎Ⅱ式）坦克是德国生产商在德军多系列坦克的技术积累下，结合战场的需求，以及吸纳了对手坦克的优点研制出来的一款高水平的坦克，其强大的装甲与火力令对手都为之称赞。</p><p>虎王Ⅵ号（虎Ⅱ式）坦克的数据为：</p><p>车长：10.3m, 车宽：3.8m, 车高：3.1m, 车重：57t; 乘员5人； 发动机700匹马力，车速：32km/h（约）, 最大行程：170km（约）; 主要武器：一门88mm Kw K43 L/71火炮，二挺7.92mm MG34机枪；装甲厚度：180mm。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>悬挂系统中负重轮也是交迭式，但外层是5个大直径的钢轮。</li><li>炮塔装备的88mm火炮身管更长。</li><li>炮塔属大型炮塔，外形较大。</li></ol></span>","caption":""}],"part2title":"战场上的Ⅵ号虎王（虎Ⅱ）坦克","part2description":"<p>1944年5月，德军Ⅵ号虎王（虎Ⅱ）坦克第一次在东线明斯克参加了战斗，继后参加了诺曼第阻击战和阿登反击战，尽管德军每个装甲单位配备的虎王数量不多，但面对数量众多的对手坦克，虎王（虎Ⅱ）坦克虎王坦克总是胜多负少。其装备的88mm Kw K43 L/71火炮，可以说是二战中最厉害的坦克炮，1000m外可击穿215mm厚装甲，4000m外可击穿88mm厚装甲；在2000mm距离就能击穿苏军的T-34坦克和盟军的M4坦克装甲（二战时，坦克交战的距离一般在800—1500m），可见虎式坦克火力的强大。虎式坦克的最大弱点是机动发性能较差，但火力和防护的强大仍使其成为了战场上的王者；但此时已是二战末期，德军已呈败势，即使有虎式坦克这样的优势武器，但都难以挽回德国法西斯的灭亡了。</p>","part2content":[{"image":"imgs/de/army/de_army_tankvi_ii_21.jpg","description":"在1944年盟军在法国诺曼第登陆后，德军的虎王坦克在诺曼第地区进行作战准备。","caption":""},{"image":"imgs/de/army/de_army_tankvi_ii_22.jpg","description":"德军的保时捷虎王坦克作战前集结。","caption":""},{"image":"imgs/de/army/de_army_tankvi_ii_23.jpg","description":"1945年春，德军509重装营的一辆虎王坦克在匈牙利一个小村庄时集结待命。","caption":""},{"image":"imgs/de/army/de_army_tankvi_ii_24.jpg","description":"1945年3月， 在匈牙利战场上被击毁的一辆德军虎王（虎Ⅱ）坦克，该坦克隶属于第501重装营。","caption":""},{"image":"imgs/de/army/de_army_tankvi_ii_25.jpg","description":"疾驰在巴黎街头的德军虎王坦克。","caption":""},{"image":"imgs/de/army/de_army_tankvi_ii_26.jpg","description":"一辆隶属德军武装党卫军第101重装甲团的虎王坦克，正在树林中隐蔽，待命出击。","caption":""},{"image":"imgs/de/army/de_army_tankvi_ii_27.jpg","description":"关于德军503重装营的纪录片其中的一个镜头，这段纪录片现在已成为德军虎王坦克的经典流传。","caption":""},{"image":"imgs/de/army/de_army_tankvi_ii_28.jpg","description":"因弹药爆炸而被完全摧毁的一辆德军第509重装营虎王坦克。","caption":""}]}')}});